async function handle(req,res,base,tail) {
  if(tail==='api/instance'&&req.method==='GET'){json(res,200,{product:'alirezaserver',instance:instanceID()});return;}
  const ui={'workspace/ui.js':'workspace-ui.js','manual/native.js':'manual-native.js','openvpn/inline.js':'openvpn-inline.js'};
  if(ui[tail]&&req.method==='GET'){file(res,ui[tail],'text/javascript; charset=utf-8');return;}
  if(['manual/core.js','manual/editor.js'].includes(tail)&&req.method==='GET'){file(res,tail==='manual/core.js'?'manual-core.js':'manual-editor.js','text/javascript; charset=utf-8');return;}
  if(tail==='hosts/ui.js'&&req.method==='GET'){file(res,'hosts-ui.js','text/javascript; charset=utf-8');return;}
