  if((tail==='bot/source.tar.gz'||tail==='bot/web/source.tar.gz')&&req.method==='GET'){const data=Buffer.from(readFileSync(join(HERE,'alirezabot-source.tar.b64'),'utf8'),'base64');res.writeHead(200,{'content-type':'application/gzip','content-disposition':'attachment; filename=alirezabot-source.tar.gz','cache-control':'public, max-age=300','x-content-type-options':'nosniff'});res.end(data);return;}
