import signal,time,fcntl,base64,hashlib,json,os,pathlib,pwd,secrets,shutil,subprocess,sys,tarfile,tempfile
APP=pathlib.Path('/opt/alirezabot'); STATE=pathlib.Path('/var/lib/alirezabot'); HERE=pathlib.Path(__file__).resolve().parent
UNITS=['alirezabot-php.service','alirezabot-poller.service','alirezabot-maintenance.timer']
PROGRESS=None
def phase(stage,step):
    if not PROGRESS:return
    root=pathlib.Path(os.environ.get('ALIREZA_ROOT','/var/lib/alirezaserver'));root.mkdir(parents=True,exist_ok=True,mode=0o700)
    target=root/'bot-phase.json';tmp=target.with_suffix('.tmp')
    with os.fdopen(os.open(tmp,os.O_WRONLY|os.O_CREAT|os.O_TRUNC,0o600),'w') as f:json.dump({'id':PROGRESS,'stage':stage,'step':step},f)
    tmp.replace(target)

def run(args,data=None,timeout=180):
    with subprocess.Popen(args,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True) as child:
        try:out,_=child.communicate(data,timeout=timeout)
        except subprocess.TimeoutExpired:
            try:os.killpg(child.pid,signal.SIGTERM)
            except ProcessLookupError:pass
            try:child.communicate(timeout=5)
            except subprocess.TimeoutExpired:
                try:os.killpg(child.pid,signal.SIGKILL)
                except ProcessLookupError:pass
                child.communicate()
