        if child.returncode:raise RuntimeError('COMMAND_FAILED:'+pathlib.Path(args[0]).name)
        return out

def status():
    output=subprocess.run(['systemctl','show','--property=Id,ActiveState',*UNITS],capture_output=True,text=True,timeout=10).stdout
    active={u:'unknown' for u in UNITS}
    for block in output.split('\n\n'):
        values=dict(line.split('=',1) for line in block.splitlines() if '=' in line)
        if values.get('Id') in active:active[values['Id']]=values.get('ActiveState','unknown')
    inbox={'failed':0,'uncertain':0,'processing':0}
    for p in (STATE/'inbox').glob('*.json'):
        try:kind=json.loads(p.read_text()).get('status');inbox[kind]=inbox.get(kind,0)+1
        except (OSError,ValueError):inbox['uncertain']+=1
    try:telegram=json.loads((STATE/'telegram-health.json').read_text())
    except (FileNotFoundError,ValueError):telegram={}
    telegram={k:telegram[k] for k in ['connected','lastPoll','errorCode'] if k in telegram}
    telegram['connected']=telegram.get('connected') is True and time.time()-telegram.get('lastPoll',0)<90 and active.get('alirezabot-poller.service')=='active'
    metrics={'users':None,'invoices':None}
    if (APP/'config.php').exists():
        try:
            script="chdir('/opt/alirezabot');require 'config.php';echo json_encode(['users'=>(int)$pdo->query('SELECT COUNT(*) FROM user')->fetchColumn(),'invoices'=>(int)$pdo->query('SELECT COUNT(*) FROM invoice')->fetchColumn()]);"
            metrics=json.loads(run(['php','-r',script],timeout=5))
        except (RuntimeError,ValueError,OSError):pass
    return {'metrics':metrics,'telegram':telegram,'inbox':inbox,'installed':(APP/'config.php').exists(),'services':active,'running':all(v=='active' for v in active.values())}
def phpvalue(v):return "'"+str(v).replace('\\','\\\\').replace("'","\\'")+"'"
def php_fpm():
    php_version=run(['php','-r','echo PHP_MAJOR_VERSION.".".PHP_MINOR_VERSION;'],timeout=15).strip()
    fpm=pathlib.Path('/usr/sbin')/('php-fpm'+php_version)
