    run(['systemctl','start','mariadb'],timeout=30)
    try:pwd.getpwnam('alirezabot')
    except KeyError:run(['useradd','--system','--home-dir',str(STATE),'--shell','/usr/sbin/nologin','alirezabot'])
    STATE.mkdir(mode=0o750,parents=True,exist_ok=True); APP.mkdir(mode=0o750,parents=True,exist_ok=True)
    phase('application',2)
    payload=base64.b64decode((HERE/'alirezabot-source.tar.b64').read_bytes(),validate=False)
    manifest=json.loads((HERE/'reference-versions.json').read_text())
    if hashlib.sha256(payload).hexdigest()!=manifest['bot']['packagedSHA256']:raise RuntimeError('BOT_PAYLOAD_CHECKSUM')
    with tempfile.TemporaryDirectory() as temp:
