pid=/run/alirezabot/php.pid
error_log=syslog
daemonize=no
[alirezabot]
user=alirezabot
group=alirezabot
listen=/run/alirezabot/php.sock
listen.mode=0660
listen.owner=root
listen.group=root
pm=ondemand
pm.max_children=3
pm.process_idle_timeout=10s
pm.max_requests=300
clear_env=yes
catch_workers_output=yes
security.limit_extensions=.php
php_admin_flag[display_errors]=off
php_admin_flag[log_errors]=on
php_admin_value[error_log]=syslog
php_admin_value[memory_limit]=192M
php_admin_value[session.save_path]=/var/lib/alirezabot
php_admin_value[opcache.enable]=1
php_admin_value[opcache.memory_consumption]=32
'''
    (APP/'php-fpm.conf').write_text(config)
    common='''After=network-online.target mariadb.service
[Service]
