 async function refresh(){if(busy)return;busy=true;try{state=await api('status');error.textContent='';const target=card.querySelector('[data-hashem-status]');target.replaceChildren();const info=document.createElement('div');info.className='azm-grid';for(const[name,value]of Object.entries(state.services||{})){const x=document.createElement('div');x.className='prof-sec';const title=document.createElement('strong');title.textContent=name;const status=document.createElement('p');status.textContent=value;x.append(title,status);info.append(x);}if(!info.children.length)info.textContent=state.installed?tr('هسته آماده است؛ هنوز تانل تنظیم نشده.','Cores are ready; no tunnel is configured yet.'):tr('هسته‌های Hashem هنوز نصب نشده‌اند.','Hashem cores are not installed yet.');target.append(info);if(state.wss&&Object.keys(state.wss).length){const p=document.createElement('p');p.dir='ltr';p.className='mono';p.textContent='WSS · '+(state.wss.stale?'stale / stopped':state.wss.connected?'connected':'disconnected')+' · sent '+(state.wss.bytes_sent||0)+' B · received '+(state.wss.bytes_recv||0)+' B'+(state.wss.last_error?' · '+state.wss.last_error:'');target.append(p);}if(state.benchmark?.samples){const b=state.benchmark;const p=document.createElement('p');p.className='mono';p.dir='ltr';p.textContent=b.kind+' · '+b.target+' · mean '+(b.meanMs?.toFixed(2)??'—')+' ms · jitter '+(b.jitterMs?.toFixed(2)??'—')+' ms · failed '+b.failures+'/'+b.samples;target.append(p);}const jobs=card.querySelector('[data-hashem-jobs]');jobs.replaceChildren();for(const j of (state.jobs||[]).slice(0,5)){const p=document.createElement('p');p.className='az-manual-note';p.textContent=j.operation+' · '+j.status+(j.error?' · '+j.error:'');jobs.append(p);}if(timer)clearTimeout(timer);if(state.busy&&card.isConnected&&!document.hidden)timer=setTimeout(refresh,2500);}catch(e){error.textContent=e.message;}finally{busy=false;}}
