// SPDX-License-Identifier: GPL-3.0-or-later
// Internal service identity, never sent to PHP or a browser. Calls the native API.
import http from 'node:http';import {pathToFileURL} from 'node:url';
let kv,auth,cached;
async function session(){if(!auth){const dir=process.env.ALIREZA_NOVA_DIR||'/opt/nova-node-agent';const k=await import(pathToFileURL(dir+'/src/kv/sqlite.mjs'));auth=await import(pathToFileURL(dir+'/src/auth.mjs'));kv=k.openKv(process.env.NOVA_DB||'/var/lib/nova/nova.db');}if(!cached||Date.now()-cached.at>300000){const s=await auth.makeSession(kv,{userAgent:'alirezabot-service'});cached={at:Date.now(),cookie:s.name+'='+s.value};}return cached.cookie;}
export function nativeClient(port,base){return async function request(route,method='GET',body,retry=true){const cookie=await session();return new Promise((resolve,reject)=>{const host='127.0.0.1:'+port;const r=http.request({hostname:'127.0.0.1',port,path:base+route,method,headers:{host,cookie,'user-agent':'alirezabot-service',origin:'http://'+host,'content-type':'application/json'},timeout:30000},res=>{let data='';res.on('data',b=>{data+=b;if(data.length>8*1024*1024)r.destroy(Error('NATIVE_RESPONSE_TOO_LARGE'));});res.on('end',async()=>{try{if(res.statusCode===401&&retry){cached=null;resolve(await request(route,method,body,false));return;}const j=JSON.parse(data);if(res.statusCode>=400)throw Object.assign(Error(j.error||'NATIVE_API_ERROR'),{status:res.statusCode});resolve(j);}catch(e){reject(e);}});});r.on('timeout',()=>r.destroy(Error('NATIVE_API_TIMEOUT')));r.on('error',reject);r.end(body?JSON.stringify(body):undefined);});};}
ALIREZA_15BEBEC436615499A4A93523

